// Create a new world and mark it as alive and as a main world, not a stage
ecs_world_t *world = ecs_init();
if (!world) { FUZZ_BAIL(); }
// Track lifecycle/state for pairing with other stubs
FUZZ_SET_ATTR_STR(world, "kind", "world");
FUZZ_SET_ATTR_INT(world, "alive", 1);
FUZZ_SET_ATTR_INT(world, "frame_open", 0);
FUZZ_SET_ATTR_INT(world, "readonly", 0);
FUZZ_SET_ATTR_STR(world, "variant", "init");
// Validation summary: returns non-null world; attributes set to enforce correct usage downstream.

// Create a minimal world and mark as alive main world
ecs_world_t *world = ecs_mini();
if (!world) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_STR(world, "kind", "world");
FUZZ_SET_ATTR_INT(world, "alive", 1);
FUZZ_SET_ATTR_INT(world, "frame_open", 0);
FUZZ_SET_ATTR_INT(world, "readonly", 0);
FUZZ_SET_ATTR_STR(world, "variant", "mini");
// Validation summary: returns non-null world; attributes set to enforce correct usage downstream.

// Build a small argv array that lives through the call
int argc = (int)(*FUZZ_PARAM(unsigned int) % 6); // 0..5
std::vector<std::string> arg_storage;
arg_storage.reserve((size_t)argc);
for (int i = 0; i < argc; i++) { arg_storage.emplace_back(FUZZ_PARAM_STR()); }
std::vector<char*> argv_vec;
argv_vec.reserve((size_t)argc);
for (int i = 0; i < argc; i++) { argv_vec.push_back(const_cast<char*>(arg_storage[(size_t)i].c_str())); }
char **argv = argc ? argv_vec.data() : nullptr;

ecs_world_t *world = ecs_init_w_args(argc, argv);
if (!world) { FUZZ_BAIL(); }
// Track lifecycle/state
FUZZ_SET_ATTR_STR(world, "kind", "world");
FUZZ_SET_ATTR_INT(world, "alive", 1);
FUZZ_SET_ATTR_INT(world, "frame_open", 0);
FUZZ_SET_ATTR_INT(world, "readonly", 0);
FUZZ_SET_ATTR_STR(world, "variant", "init_w_args");
// Validation summary: argv meets lifetime/length requirements for the call; world non-null and attributes set.

// Enforce that input is a main world, not a stage, and is alive
const char *kind = FUZZ_GET_ATTR_STR(world, "kind");
int alive = FUZZ_GET_ATTR_INT(world, "alive");
int frame_open = FUZZ_GET_ATTR_INT(world, "frame_open");
int readonly = FUZZ_GET_ATTR_INT(world, "readonly");
if (!kind || kind[0] == '\0' || strcmp(kind, "world") != 0) { FUZZ_BAIL(); }
if (!alive) { FUZZ_BAIL(); }
// Must not finalize while a frame is open or in readonly mode
if (frame_open) { FUZZ_BAIL(); }
if (readonly) { FUZZ_BAIL(); }

(void)ecs_fini(world);
// Mark as dead; do not return destroyed world as output
FUZZ_SET_ATTR_INT(world, "alive", 0);
// Validation summary: Only finalizes live main worlds with no open frame/readonly; world is not returned (ownership ends).

// World must be valid; call query API
(void)ecs_is_fini(world);
// Keep world alive in pool
// Validation summary: Read-only query; world returned unchanged.

// Register a fini callback; provide a valid function pointer and optional ctx
ecs_fini_action_t fn = +[](ecs_world_t *w, void *ctx){ (void)w; (void)ctx; };
void *ctx = nullptr; // avoid lifetime issues
ecs_atfini(world, fn, ctx);
// Validation summary: Registers a valid callback before fini; world returned for reuse.

// Obtain view of entity ids; do not mutate/free returned storage
ecs_entities_t ents = ecs_get_entities(world);
// Basic sanity checks on counts
if (ents.count < 0 || ents.alive_count < 0) { FUZZ_BAIL(); }
if (ents.alive_count > ents.count) { FUZZ_BAIL(); }
// Keep world for reuse
// Validation summary: Enforces non-negativity and alive<=count; does not touch returned memory.

// Must be paired with frame_end and only when not already inside a frame
if (FUZZ_GET_ATTR_INT(world, "frame_open")) { FUZZ_BAIL(); }
// Generate a small delta time; 0 disables pacing, positive values allowed
double dt = (double)((*FUZZ_PARAM(unsigned int) % 1001) / 1000.0); // 0.000..1.000
(void)ecs_frame_begin(world, (ecs_ftime_t)dt);
FUZZ_SET_ATTR_INT(world, "frame_open", 1);
// Validation summary: Ensures pairing (no nesting) via frame_open attribute; world returned for frame_end.

// Must be called after a matching frame_begin
if (!FUZZ_GET_ATTR_INT(world, "frame_open")) { FUZZ_BAIL(); }
ecs_frame_end(world);
FUZZ_SET_ATTR_INT(world, "frame_open", 0);
// Validation summary: Enforces begin/end pairing; clears frame_open flag and returns world.

// Schedule a one-shot post-frame action; provide a valid function pointer
ecs_fini_action_t fn = +[](ecs_world_t *w, void *ctx){ (void)w; (void)ctx; };
void *ctx = nullptr; // avoid leaking user memory since execution timing is external
ecs_run_post_frame(world, fn, ctx);
// Validation summary: Valid callable registered; uses null ctx to avoid lifetime hazards; world returned.

// Signal application quit; world must be valid
ecs_quit(world);
// Validation summary: Simple signal; world remains valid and is returned.

bool enable = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;
ecs_measure_frame_time(world, enable);
// Validation summary: Toggles measurement with a valid bool; world returned.

bool enable = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;
ecs_measure_system_time(world, enable);
// Validation summary: Toggles system timing; world returned.

// Choose fps in [0, 240]; 0 disables limiting
double fps = (double)(*FUZZ_PARAM(unsigned int) % 241);
ecs_set_target_fps(world, (ecs_ftime_t)fps);
// Validation summary: Accepts 0 (disable) or positive limit; world returned.

ecs_flags32_t flags = (ecs_flags32_t)(*FUZZ_PARAM(unsigned int));
ecs_set_default_query_flags(world, flags);
// Validation summary: Sets arbitrary combination; world returned.

// Enter readonly; must not already be in readonly according to our tracked state
if (FUZZ_GET_ATTR_INT(world, "readonly")) { FUZZ_BAIL(); }
bool multi_threaded = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;
(void)ecs_readonly_begin(world, multi_threaded);
FUZZ_SET_ATTR_INT(world, "readonly", 1);
FUZZ_SET_ATTR_INT(world, "readonly_mt", multi_threaded ? 1 : 0);
// Validation summary: Tracks readonly state to enforce pairing with readonly_end; world returned.

// Must match a prior readonly_begin
if (!FUZZ_GET_ATTR_INT(world, "readonly")) { FUZZ_BAIL(); }
ecs_readonly_end(world);
FUZZ_SET_ATTR_INT(world, "readonly", 0);
FUZZ_SET_ATTR_INT(world, "readonly_mt", 0);
// Validation summary: Enforces correct pairing; clears readonly flags and returns world.

// Create a stage from the world, merge its commands, then free the stage
// This ensures we pass a stage pointer to ecs_merge as required by the API
ecs_world_t *stage = ecs_stage_new(world);
if (!stage) { FUZZ_BAIL(); }
// Optionally enqueue deferred ops on stage to make merge meaningful
// Keep it simple here; merge is valid even if no commands were queued
ecs_merge(stage);
// Free the unmanaged stage after merge to avoid leaks
ecs_stage_free(stage);
// Validation summary: Provides a valid stage to ecs_merge and frees it; world returned for reuse.

// Begin deferring operations. Enforce pairing and idempotence via attributes.
if (FUZZ_GET_ATTR_INT(world, "readonly")) { /* allowed but ensure we track separately */ }
if (FUZZ_GET_ATTR_INT(world, "defer")) { FUZZ_BAIL(); }
bool switched = ecs_defer_begin(world);
// Track that we're now deferring regardless of whether API reports a switch
FUZZ_SET_ATTR_INT(world, "defer", 1);
FUZZ_SET_ATTR_INT(world, "defer_suspended", 0);
(void)switched;
// Validation summary: ensures defer isn't already active; marks defer active for correct pairing.

// End deferring operations. Must follow ecs_defer_begin and not be suspended.
if (!FUZZ_GET_ATTR_INT(world, "defer")) { FUZZ_BAIL(); }
// If currently suspended, resume first to satisfy API expectation that end follows active deferral
if (FUZZ_GET_ATTR_INT(world, "defer_suspended")) { ecs_defer_resume(world); FUZZ_SET_ATTR_INT(world, "defer_suspended", 0); }
bool switched = ecs_defer_end(world);
FUZZ_SET_ATTR_INT(world, "defer", 0);
(void)switched;
// Validation summary: enforces begin/end pairing and clears tracking flags.

// Suspend deferring temporarily. Requires deferring to be enabled and not already suspended.
if (!FUZZ_GET_ATTR_INT(world, "defer")) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(world, "defer_suspended")) { FUZZ_BAIL(); }
ecs_defer_suspend(world);
FUZZ_SET_ATTR_INT(world, "defer_suspended", 1);
// Validation summary: only suspends when deferring is active and not already suspended.

// Resume deferring after suspend. Must be called while suspended and before defer_end.
if (!FUZZ_GET_ATTR_INT(world, "defer")) { FUZZ_BAIL(); }
if (!FUZZ_GET_ATTR_INT(world, "defer_suspended")) { FUZZ_BAIL(); }
ecs_defer_resume(world);
FUZZ_SET_ATTR_INT(world, "defer_suspended", 0);
// Validation summary: enforces suspend/resume pairing and updates suspension flag.

// Query whether deferring is enabled for current stage/world
(void)ecs_is_deferred(world);
// Validation summary: read-only query; world returned unchanged.

// Query whether deferring is currently suspended
(void)ecs_is_defer_suspended(world);
// Validation summary: read-only query; world returned unchanged.

// Configure a positive number of stages for multithreading/deferred queues
int32_t stages = (int32_t)(*FUZZ_PARAM(unsigned int) % 4u) + 1; // [1..4]
ecs_set_stage_count(world, stages);
// Track for other stubs that need a valid index range
FUZZ_SET_ATTR_INT(world, "stages", stages);
// Validation summary: sets stages >= 1 and records it for ecs_get_stage.

// Retrieve current stage count
(void)ecs_get_stage_count(world);
// Validation summary: simple getter; world returned unchanged.

// Obtain a stage handle by index in range [0, stage_count)
int32_t count = ecs_get_stage_count(world);
if (count <= 0) {
    // Ensure a non-zero stage count when not configured
    count = (int32_t)(*FUZZ_PARAM(unsigned int) % 4u) + 1;
    ecs_set_stage_count(world, count);
    FUZZ_SET_ATTR_INT(world, "stages", count);
}
int32_t stage_id = (int32_t)(*FUZZ_PARAM(unsigned int) % (uint32_t)count);
ecs_world_t *stage = ecs_get_stage(world, stage_id);
if (!stage) { FUZZ_BAIL(); }
// Track that this is a managed (internal) stage owned by the world
FUZZ_SET_ATTR_STR(stage, "kind", "stage");
FUZZ_SET_ATTR_INT(stage, "alive", 1);
FUZZ_SET_ATTR_INT(stage, "unmanaged_stage", 0);
FUZZ_SET_ATTR_PTR(stage, "parent_world", (void*)world);
// Validation summary: ensures valid stage_id, returns stage marked as managed (not to be freed by ecs_stage_free).

// Works for a world or a stage pointer
(void)ecs_stage_is_readonly(world);
// Validation summary: read-only query about readonly state; world returned.

// Create an unmanaged stage that must be freed with ecs_stage_free
ecs_world_t *stage = ecs_stage_new(world);
if (!stage) { FUZZ_BAIL(); }
// Mark stage metadata for lifecycle management
FUZZ_SET_ATTR_STR(stage, "kind", "stage");
FUZZ_SET_ATTR_INT(stage, "alive", 1);
FUZZ_SET_ATTR_INT(stage, "unmanaged_stage", 1);
FUZZ_SET_ATTR_INT(stage, "defer", 0);
FUZZ_SET_ATTR_INT(stage, "defer_suspended", 0);
FUZZ_SET_ATTR_INT(stage, "readonly", 0);
FUZZ_SET_ATTR_PTR(stage, "parent_world", (void*)world);
// Validation summary: ensures stage is created and marked unmanaged so only ecs_stage_free consumes it.

// Free an unmanaged stage created by ecs_stage_new; must not be a managed stage from ecs_get_stage
