import random
import string
from typing import List

# Data type: command-line argument string
# We generate a buffer that the fuzzing harness will split into multiple argv strings
# via repeated FUZZ_PARAM_STR() calls. We therefore pack multiple C-style strings
# back-to-back, each NUL-terminated, so the fuzzer can consume them independently.
# Focus on interesting argv patterns: program name, flags, options with values,
# paths, environment-like tokens, unicode, very long arg, empty string, and edge cases.

MAX_TOTAL = 4096

def _rand_ascii(r: random.Random, length: int) -> str:
    alphabet = string.ascii_letters + string.digits + "-_./:\\"
    return ''.join(r.choice(alphabet) for _ in range(length))

def _rand_utf8(r: random.Random, length: int) -> bytes:
    # Mix simple ASCII with some multi-byte UTF-8 sequences
    parts: List[bytes] = []
    while len(b''.join(parts)) < length:
        choice = r.randrange(10)
        if choice < 6:
            parts.append(bytes([r.choice(b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_.:/\\" )]))
        else:
            # pick from a few common multibyte sequences
            seq = r.choice([
                "✓", "é", "Ω", "汉", "字", "😀", "ß", "ø", "ñ"
            ]).encode('utf-8')
            parts.append(seq)
    out = b''.join(parts)
    return out[:length]

def _make_flag(r: random.Random) -> str:
    forms = [
        "-h", "--help", "-v", "--version", "-q", "--quiet", "-O2",
        "--opt", "--no-color", "-I", "-L", "-DDEBUG", "--debug",
    ]
    f = r.choice(forms)
    # Occasionally attach an equals-style value
    if r.random() < 0.3 and f.startswith("--"):
        val = _rand_ascii(r, r.randint(1, 12))
        f = f + "=" + val
    return f

def _make_option_with_value(r: random.Random) -> List[bytes]:
    # Either separate arg for value, or --key=value
    key = r.choice(["--output", "--config", "--path", "--mode", "--threads"])    
    if r.random() < 0.5:
        val = r.choice([
            _rand_ascii(r, r.randint(1, 16)),
            "~/proj/build/out.bin",
            "/tmp/σ/файл.txt",
            "C:\\Program Files\\App\\app.exe",
            str(r.randint(0, 128)),
        ])
        return [key.encode('utf-8'), str(val).encode('utf-8')]
    else:
        val = r.choice([
            _rand_ascii(r, r.randint(1, 16)),
            "fast", "slow", "balanced",
            "/var/log/app.log",
        ])
        return [f"{key}={val}".encode('utf-8')]

def _make_path(r: random.Random) -> str:
    if r.random() < 0.5:
        # Unix-like path
        parts = ["/"] + [_rand_ascii(r, r.randint(1, 8)) for _ in range(r.randint(1, 4))]
        return "/".join(p.strip('/') for p in parts)
    else:
        # Windows-like path
        drive = r.choice(list(string.ascii_uppercase)) + ":\\"
        segs = [_rand_ascii(r, r.randint(1, 8)) for _ in range(r.randint(1, 4))]
        return drive + "\\".join(segs)

def _make_progname(r: random.Random) -> str:
    base = r.choice(["app", "demo", "flecs", "test", "runner", "μsvc"]) 
    if r.random() < 0.5:
        base += str(r.randint(0, 9))
    if r.random() < 0.4:
        base += r.choice([".exe", ".bin", ""])
    return base

def _make_env_like(r: random.Random) -> str:
    key = r.choice(["PATH", "HOME", "USER", "LANG", "FLECS_FLAGS"]) 
    if key == "PATH":
        sep = ";" if r.random() < 0.5 else ":"
        val = sep.join(_make_path(r) for _ in range(r.randint(1, 4)))
    else:
        val = _rand_ascii(r, r.randint(3, 12))
    return f"{key}={val}"

def _make_long_arg(r: random.Random, target_len: int) -> bytes:
    # Create a long but valid printable/utf-8 argument
    if r.random() < 0.5:
        return _rand_ascii(r, target_len).encode('utf-8')
    else:
        return _rand_utf8(r, target_len)

def _pack_args(args: List[bytes]) -> bytes:
    # Join as independent C strings for FUZZ_PARAM_STR consumption
    # Ensure each has no embedded NUL and add final NUL per string.
    out = bytearray()
    for a in args:
        a = a.replace(b"\x00", b"")
        out += a + b"\x00"
    return bytes(out)

def generate(seed: int) -> bytes:
    r = random.Random(seed)

    # Choose argc 0..5 to match stub behavior
    argc = r.randint(0, 5)

    args: List[bytes] = []

    if argc > 0:
        # argv[0] program name
        prog = _make_progname(r).encode('utf-8')
        args.append(prog)

    # Fill the rest with diverse, valid arguments
    while len(args) < argc:
        choice = r.randrange(10)
        if choice == 0:
            args.append(_make_flag(r).encode('utf-8'))
        elif choice == 1:
            args.extend(_make_option_with_value(r))
        elif choice == 2:
            args.append(_make_path(r).encode('utf-8'))
        elif choice == 3:
            args.append(_make_env_like(r).encode('utf-8'))
        elif choice == 4:
            # empty argument
            args.append(b"")
        elif choice == 5:
            # unicode heavy
            args.append(_rand_utf8(r, r.randint(1, 24)))
        elif choice == 6:
            # repeated short flags combined
            flags = "-" + ''.join(r.choice("abcdexyz012") for _ in range(r.randint(2,6)))
            args.append(flags.encode('utf-8'))
        elif choice == 7:
            # value starting with dash to test option parsing edge
            args.append(("-" + _rand_ascii(r, r.randint(1, 10))).encode('utf-8'))
        elif choice == 8:
            # long arg but bounded to keep under MAX_TOTAL
            remaining = MAX_TOTAL - (len(_pack_args(args)) if args else 0) - 16
            remaining = max(8, min(256, remaining))
            args.append(_make_long_arg(r, r.randint(32, remaining)))
        else:
            # mixed key:value style
            k = _rand_ascii(r, r.randint(3, 8))
            v = _rand_ascii(r, r.randint(0, 12))
            args.append(f"{k}:{v}".encode('utf-8'))

        # Trim if we exceeded argc due to options-with-value adding two args
        if len(args) > argc:
            args = args[:argc]

    buf = _pack_args(args)

    # Ensure total size bounded
    if len(buf) > MAX_TOTAL:
        buf = buf[:MAX_TOTAL]
        # Ensure last byte terminates a string
        if not buf.endswith(b"\x00"):
            buf = buf[:-1] + b"\x00"

    return buf

import random
import string
from typing import List

# Generator for ECS id expression string
# Aim: produce valid, interesting id expressions covering:
# - plain identifiers (component names)
# - numeric ids (entity numbers)
# - pairs (Rel,Target) with different spacings
# - wildcards (*) and any (_)
# - flags on ids like toggles not directly encoded here, but include common forms
# - namespaced paths with separators '::' and '.' and custom prefixes
# - quoted identifiers to include special characters
# - combinations with OR '|' not part of single id, so avoid; keep to single-id syntax
# - optional leading/trailing spaces
# - hash/symbol-like identifiers
# The parser may require the script addon; even if parsing returns 0, inputs should be well-formed.

MAX_LEN = 4096

NAMES = [
    "Position", "Velocity", "Mass", "Name", "Renderable", "Transform",
    "Parent", "ChildOf", "IsA", "Tag", "Health", "Mana", "AI",
    "Player", "Enemy", "Ally", "Damage", "Healed", "Inventory",
    "Relationship", "Target", "Owner", "OwnedBy", "Contains",
]

NAMESPACES = ["core", "game", "physics", "gfx", "ui", "net"]

# Characters allowed in identifiers (unquoted)
IDENT_CHARS = string.ascii_letters + string.digits + "_"


def rand_ident(r: random.Random) -> str:
    # 60% choose from predefined, 40% synthesize
    if r.random() < 0.6:
        base = r.choice(NAMES)
    else:
        ln = r.randint(1, 12)
        base = r.choice(string.ascii_uppercase)
        base += ''.join(r.choice(IDENT_CHARS) for _ in range(ln))
    # Optionally namespace-qualify with '.' or '::'
    qual = r.random()
    if qual < 0.25:
        ns = r.choice(NAMESPACES)
        return f"{ns}.{base}"
    elif qual < 0.5:
        ns = r.choice(NAMESPACES)
        return f"{ns}::{base}"
    else:
        return base


def quoted_ident(r: random.Random) -> str:
    # Produce a quoted identifier allowing spaces and punctuation
    specials = " -:/#@!$%^&*+?<>|"
    ln = r.randint(1, 16)
    s = ''.join(r.choice(string.ascii_letters + string.digits + specials) for _ in range(ln))
    # Escape quotes by backslash in case parser supports it
    s = s.replace('"', '\\"')
    return f'"{s}"'


def numeric_id(r: random.Random) -> str:
    # ecs ids are 64-bit, but textual numeric likely decimal; keep within 32-bit sometimes
    if r.random() < 0.7:
        val = r.randint(1, 2**31 - 1)
    else:
        val = r.randint(2**31, 2**48)  # still within 64-bit
    return str(val)


def maybe_flags(r: random.Random) -> str:
    # Some parsers accept suffix flags like "|TOGGLE" or similar, but not standardized across builds.
    # To stay valid broadly, return empty most of the time.
    return ""


def wildcard(r: random.Random) -> str:
    return r.choice(["*", "_", "Any", "Any_*"][:2])  # keep to * and _ for portability


def pair_expr(r: random.Random) -> str:
    # Generate a pair like (Rel,Target) with optional spaces and mixed forms (ident/numeric/wildcard)
    def any_id() -> str:
        t = r.random()
        if t < 0.45:
            return rand_ident(r)
        elif t < 0.6:
            return quoted_ident(r)
        elif t < 0.8:
            return numeric_id(r)
        else:
            return wildcard(r)

    rel = any_id()
    tgt = any_id()
    # Random spacing
    sp1 = "" if r.random() < 0.5 else " " * r.randint(1, 3)
    sp2 = "" if r.random() < 0.5 else " " * r.randint(1, 3)
    sp3 = "" if r.random() < 0.5 else " " * r.randint(1, 3)
    return f"({sp1}{rel}{sp2},{sp3}{tgt}{sp1})"


def single_id_expr(r: random.Random) -> str:
    t = r.random()
    if t < 0.35:
        s = rand_ident(r)
    elif t < 0.5:
        s = quoted_ident(r)
    elif t < 0.7:
        s = numeric_id(r)
    elif t < 0.9:
        s = pair_expr(r)
    else:
        s = wildcard(r)
    return s + maybe_flags(r)


def add_prefix_suffix(r: random.Random, s: str) -> str:
    # Optional root prefix like ":" used in flecs paths; or leading/trailing spaces
    # Keep conservative for id parsing: occasionally add spaces
    if r.random() < 0.3:
        s = " " * r.randint(1, 3) + s
    if r.random() < 0.3:
        s = s + " " * r.randint(1, 3)
    # Rarely add root prefix "::" or "/" at start to simulate absolute paths
    if r.random() < 0.15 and not s.startswith("("):
        pref = r.choice(["::", "/"])  # keep to common path-like markers
        s = pref + s.lstrip()
    return s


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Choose between single id and pair; ensure within size limits
    expr = single_id_expr(r)
    expr = add_prefix_suffix(r, expr)
    # Ensure not exceeding max length
    if len(expr) > MAX_LEN:
        expr = expr[:MAX_LEN]
    return expr.encode("utf-8")
